with not_flagged as (select s.* from customers s where not exists (select 1 from subscriptions x where x.customer_id = s.id and x.end_date < s.signup_date)) select segment, sum(case when segment = 'SMB' then credit_limit else 0 end) as smb_credit_limit, sort_array(collect_set(segment)) as segment_list, percentile_approx(credit_limit, array(0.25, 0.5, 0.75)) as credit_limit_quartiles from not_flagged group by segment;
